          "source": "synthetic fixture",
          "quote": "\"status\": \"failed\", \"success_proven\": false"
        },
        {
          "source": "turn 2 gate",
          "quote": "The assistant only asked for confirmation; it did not confirm that the contact name was corrected."
        }
      ]
